'use strict';
(function(root){function install(E){const P=E.Game.prototype;if(P.fusionRuntime)return;P.fusionRuntime=true;const old={action:P.performSkillAction,tech:P.tickTechniques,ready:P.autoSkillReady,cast:P.castSkill};const kinds=['fire','water','wind','earth'],active=g=>g.s.active===11&&g.h.cell===4,live=g=>g.c.enemies.filter(e=>e.hp>0),units=g=>g.c.devices.filter(p=>p.fourElement&&p.life>0),fused=g=>units(g).find(p=>p.appearance==='fusion');
function pulse(g,ctx,element,p){g.emit('skill',{...ctx.event,heroId:11,cell:4,phase:true,element,from:{x:p.x,y:p.y},x:p.x,y:p.y});}
function spawn(g,kind,ctx,origin=null){const i=kinds.indexOf(kind),fusion=kind==='fusion',o=origin||g.c,pos=E.safePoint({x:o.x+(fusion?70:45+(i%2)*45),y:o.y+(fusion?0:-40+Math.floor(i/2)*75)},g.c.zone),p={...pos,kind:'spirit',fourElement:true,undead:true,appearance:kind,skin:fusion?'fusion':'element-'+kind,name:fusion?'사원소 융합체':{fire:'불꽃 정령',water:'물방울 정령',wind:'돌풍 정령',earth:'바위 정령'}[kind],life:fusion?8:24,timer:.15*Math.max(0,i),lastAttack:-99,renderHeight:fusion?78:kind==='earth'?44:38,damage:ctx.attack,ctx,petHP:1e9,maxPetHP:1e9};g.c.devices.push(p);return p;}
function strike(g,p,element,t,multi=1){if(!t||t.hp<=0)return;const ctx=p.ctx,power=element==='earth'?1.5:element==='fire'?.9:element==='water'?.65:.8,hit=e=>g.damageTechnique(e,power*multi,ctx);if(element==='fire'){for(const e of live(g).filter(e=>E.dist(e,t)<85))hit(e);}else if(element==='water'){hit(t);t.fusionSlow=Math.max(t.fusionSlow||0,2.5);}else if(element==='wind'){const dx=t.x-p.x,dy=t.y-p.y,len=Math.hypot(dx,dy)||1;for(const e of live(g)){const along=((e.x-p.x)*dx+(e.y-p.y)*dy)/len,side=Math.abs((e.x-p.x)*dy-(e.y-p.y)*dx)/len;if(along>=0&&along<=340&&side<24)hit(e);}}else for(const e of live(g).filter(e=>E.dist(e,t)<65)){hit(e);e.root=Math.max(e.root||0,e.boss?.18:.5);}p.lastAttack=g.time;g.emit('skill',{...ctx.event,heroId:11,cell:4,phase:true,element,from:{x:p.x,y:p.y-18},x:t.x,y:t.y,fusionHit:true,fusionActor:p.appearance==='fusion'});}
function combo(g,ps,boost){const c=g.c;ps.forEach((p,i)=>g.queueSkill(i*.2,()=>{if(g.c!==c||c.hp<=0||c.deadTimer>0||c.transition>0||!units(g).includes(p))return;const t=live(g).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(t&&E.dist(p,t)<420)strike(g,p,p.appearance==='fusion'?kinds[i%4]:p.appearance,t,boost);}));}
P.performSkillAction=function(a,ctx){if(a.op!=='fusion-kit')return old.action.call(this,a,ctx);const c=this.c;if(c!==ctx.combat||c.hp<=0)return;switch(a.kind){case'four-call':if(!fused(this)){const was=units(this).length;c.devices=c.devices.filter(p=>!p.fourElement);for(const k of kinds)spawn(this,k,ctx);if(!was)c.fourSince=this.time;pulse(this,ctx,'summon',c);}break;case'convergence':combo(this,units(this),1.4);break;case'resonance':for(const p of units(this)){p.resonance=8;p.ctx=ctx;}pulse(this,ctx,'resonance',c);break;case'overdrive':{if(fused(this)||!kinds.every(k=>units(this).some(p=>p.appearance===k)))return;const source=units(this)[0].ctx;c.devices=c.devices.filter(p=>!p.fourElement);const p=spawn(this,'fusion',ctx);p.restoreCtx=source;pulse(this,ctx,'merge',p);combo(this,[p,p,p,p],2);this.queueSkill(1.35,()=>{if(this.c!==c||c.hp<=0||c.deadTimer>0||c.transition>0||!units(this).includes(p))return;const t=live(this).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(t&&E.dist(p,t)<420){for(const e of live(this).filter(e=>E.dist(e,t)<160))this.damageTechnique(e,4,ctx);pulse(this,ctx,'all',t);}});break;}}};
P.autoSkillReady=function(d,t){if(d.actions[0]?.op==='fusion-kit'){const k=d.actions[0].kind,ps=units(this),p=fused(this);if(k==='four-call')return !p&&(ps.length<4||ps.some(p=>p.life<3));if(k==='convergence')return ps.length>0;if(k==='resonance')return ps.length>0&&!ps.some(p=>p.resonance>1);if(k==='overdrive')return !p&&ps.length===4&&this.time-(this.c.fourSince??this.time)>=6&&live(this).some(e=>e.boss||live(this).filter(e=>E.dist(e,this.c)<420).length>=3);}return old.ready.call(this,d,t);};
P.castSkill=function(slot,manual=true){const d=this.skillSpec(slot);if(active(this)&&d?.actions[0]?.op==='fusion-kit'){const k=d.actions[0].kind,ps=units(this);if(k==='four-call'&&fused(this)||['convergence','resonance'].includes(k)&&!ps.length||k==='overdrive'&&(fused(this)||!kinds.every(k=>ps.some(p=>p.appearance===k))))return false;}return old.cast.call(this,slot,manual);};
P.tickTechniques=function(dt){const c=this.c,ps=c.devices.filter(p=>p.fourElement);for(const e of live(this))e.fusionSlow=Math.max(0,(e.fusionSlow||0)-dt);c.devices=c.devices.filter(p=>!p.fourElement);const result=old.tech.call(this,dt);for(const p of ps){p.life-=dt;p.timer-=dt;p.resonance=Math.max(0,(p.resonance||0)-dt);if(p.life<=0){if(p.appearance==='fusion'&&active(this)&&c.hp>0&&!c.deadTimer&&!c.transition){for(const k of kinds)spawn(this,k,p.restoreCtx||p.ctx,{x:p.x-60,y:p.y});c.fourSince=this.time;pulse(this,p.ctx,'split',p);}continue;}if(c.hp<=0||c.deadTimer||c.transition)continue;const t=live(this).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(!t)continue;const range=p.appearance==='earth'?55:260,d=E.dist(p,t);p.facing=t.x<p.x;if(d>range){const step=Math.min(dt*75,d-range),pos=E.safePoint({x:p.x+(t.x-p.x)/d*step,y:p.y+(t.y-p.y)/d*step},c.zone);p.x=pos.x;p.y=pos.y;}if(d<=range+8&&p.timer<=0){if(p.appearance==='fusion'){p.elementIndex=((p.elementIndex??-1)+1)%4;strike(this,p,kinds[p.elementIndex],t,1.8);p.timer=.5;}else{strike(this,p,p.appearance,t,p.resonance>0?1.25:1);p.timer=(p.appearance==='earth'?1.7:1.3)/(p.resonance>0?1.25:1);}}}c.devices=c.devices.concat(ps.filter(p=>p.life>0));return result;};
}if(typeof module!=='undefined')module.exports=install;root.RPG_FUSION_RUNTIME={install};})(typeof window!=='undefined'?window:globalThis);
